<?php require_once __DIR__.'/../includes/bootstrap.php';$id=$_SESSION['pending_2fa']??null;if(!$id)redirect('/login.php');$subject='2fa:'.$id;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=preg_replace('/\D/','',$_POST['code']??'');if(rate_limited($subject,5,10)){flash('error','Too many codes were rejected. Sign in again later.');redirect('/login.php');}$q=db()->prepare('SELECT * FROM users WHERE id=? AND totp_enabled=1');$q->execute([$id]);$u=$q->fetch();$ok=$u&&strlen($code)===6&&totp()->verifyKey(decrypt_secret($u['totp_secret_enc']),$code,1);log_attempt($subject,(bool)$ok);if($ok){complete_login($u);redirect($u['role']==='ADMIN'?'/admin/dashboard.php':'/dashboard.php');}flash('error','The code was not accepted. Try the current six-digit code.');}
render_start('Verify your identity');?><p class="lede">Enter the current six-digit code from your authenticator app.</p><form method="post"><?=csrf_field()?><label>6-digit code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required autofocus></label><button class="button">Verify and sign in</button></form><?php render_end();
